import{_ as e,o as l,c as o,a0 as t}from"./chunks/framework.jwovEGr5.js";const _=JSON.parse('{"title":"简介","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"理论学习/简介.md","filePath":"理论学习/简介.md"}'),i={name:"理论学习/简介.md"};function r(p,a,n,c,d,s){return l(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h1><p>理论学习经验总结，主要以视频课程笔记为主，以及ai辅助学习内容</p><h2 id="编程语言" tabindex="-1">编程语言 <a class="header-anchor" href="#编程语言" aria-label="Permalink to &quot;编程语言&quot;">​</a></h2><p>是人和计算机沟通的一套规则</p><h2 id="前端与后端" tabindex="-1">前端与后端 <a class="header-anchor" href="#前端与后端" aria-label="Permalink to &quot;前端与后端&quot;">​</a></h2><h3 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h3><p>Front‑end，客户端</p><p>用户可以直接看到、交互的一切，所见即所得</p><h3 id="后端" tabindex="-1">后端 <a class="header-anchor" href="#后端" aria-label="Permalink to &quot;后端&quot;">​</a></h3><p>Back‑end，服务端</p><p>用户无法看见，运行在服务器电脑上，处理业务逻辑、存储数据</p><h2 id="有关信息" tabindex="-1">有关信息 <a class="header-anchor" href="#有关信息" aria-label="Permalink to &quot;有关信息&quot;">​</a></h2><p>内容来自：bilibili@英雄哪里出来</p><p>视频 <a href="https://www.bilibili.com/video/BV1Tejc6oEik/?spm_id_from=333.1387.collection.video_card.click&amp;vd_source=c5b001da49827c95685ff66b3392ffc9" target="_blank" rel="noreferrer">10分钟app开发全流程</a> 评论：</p><hr><p>当你在Vibe Coding用AI来生成应用的时候，至少需要能够鉴别出来前端界面上哪些信息是假的。</p><p>因为AI生成的前端界面，核心逻辑是优先满足「视觉好看、页面完整、一眼看上去能跑通」，为了让界面看起来足够真实、没有空白占位，AI会自动填充大量伪造的静态模拟数据。而这些假数据，绝大多数都是前端代码脱离后端、脱离数据库、脱离大模型能力凭空写死的常量数据：一部分是前端纯静态写死的文案、数字、列表；另一部分是前端定时器、假接口mock出来的固定返回值。</p><p>更关键的是：这类数据本身是前端无法自行计算、无法本地生成、无法通过前端JS逻辑推导出来的，必须依赖后端接口、数据库持久化存储，或是调用大模型进行实时推理才能产出真实结果。</p><p>如果你本身没有任何前后端开发的经验，这个视频可以好好研究下，视频中遇到不会的词汇，可以让AI给你好好解释一下，完整跑通一个MVP版本，就知道做项目是怎么回事了。至于为什么要有后端，为什么区分前后端，为什么要有数据库，为什么要有大模型，为什么不能前端直接调用大模型，原因是后端的作用很多，主要有：</p><ol><li>前端代码完全透明，无法做核心业务校验</li></ol><p>用户可以轻松打开浏览器控制台篡改JS变量、修改请求参数，比如修改订单价格、会员权限、积分数值。如果没有后端二次校验，篡改后的非法数据会直接生效；后端可以统一做参数合法性校验、权限鉴权，拦住客户端所有恶意修改。</p><ol start="2"><li>前端无法管控外部接口密钥与敏感配置</li></ol><p>大模型API Key、数据库账号密码、第三方服务凭证一旦写在前端代码里，任何人查看源码、抓包就能直接窃取，被盗刷扣费、盗用接口资源是必然结果，后端可以对内保管所有私密凭证，只对外暴露轻量化业务接口。</p><ol start="3"><li>承接跨层调度，串联数据库与大模型</li></ol><p>前端没有稳定能力直连数据库（数据库端口公网暴露风险极高，浏览器也不支持数据库原生协议），也不适合直接管理大模型请求队列；后端作为中间层，统一分发普通业务请求至数据库、智能生成请求至大模型，统一格式化出入参，抹平不同服务的接口差异。</p><ol start="4"><li>实现限流、熔断、日志与运维管控</li></ol><p>大量用户同时发起AI问答请求时，前端无法控制并发量，极易造成模型接口超额扣费、服务崩溃；后端可以配置请求限流、超时重试、异常熔断，同时记录每一次调用日志，方便后续排查报错、统计用量。</p><p>数据库核心作用就是存盘，当然数据库本身也是一个服务</p><ol><li>内存与前端本地数据无法持久留存</li></ol><p>前端localStorage存储容量有限，且跟随浏览器设备绑定，换设备就丢失；后端内存数据会在服务重启、进程崩溃后全部清空。而用户对话历史、订单记录、个人配置、模型调用日志这类数据，需要长期稳定保存，只有数据库可以实现断电、重启后数据不丢失。</p><ol start="2"><li>实现多端数据同步与多用户隔离</li></ol><p>同一个账号在手机、电脑两端访问应用时，需要加载统一的对话历史与业务数据，前端本地存储做不到跨设备同步；数据库可以绑定用户唯一ID，隔离不同用户的数据，实现多端互通、权限隔离。</p><ol start="3"><li>支撑数据检索、筛选、统计与扩展</li></ol><p>AI生成的假列表只能固定顺序展示，而真实场景需要按时间筛选对话、按关键词检索历史问答、统计月度模型调用次数，数据库提供索引、查询、聚合能力，是批量数据处理的基础。</p><ol start="4"><li>保障数据安全与可回溯</li></ol><p>数据库支持定时备份、事务回滚、操作日志记录，误删除对话、异常写入脏数据时可以恢复；前端静态假数据、无备份内存数据一旦改动，无法回退修复。</p>',36)])])}const f=e(i,[["render",r]]);export{_ as __pageData,f as default};
